src\\styles.css:
/* Shared typography: native fonts keep the interface available without downloads. */
:root {
  --font-ui: 'Segoe UI', system-ui, -apple-system, BlinkMacSystemFont, Roboto, 'Helvetica Neue', Arial, sans-serif;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-heading: clamp(1.5rem, 1.25rem + 1vw, 1.875rem);
  --text-primary: #1f2937;
  --text-secondary: #475569;
}

html { font-size: 100%; }
.form-guide { padding: 14px 18px; background: #eff6ff; border-left: 3px solid #93b4e4; border-radius: 0 8px 8px 0; color: #334155; font-size: .9375rem; line-height: 1.6; }
.filter-panel { padding: 20px; margin-bottom: 20px; background: white; border: 1px solid #dbe2ea; border-radius: 10px; }
.filter-panel label { display: block; margin-bottom: 8px; font-weight: 600; }
.filter-controls { display: flex; flex-wrap: wrap; gap: 12px; }
.filter-controls input { flex: 1 1 240px; min-width: 0; padding: 10px 12px; border: 1px solid #94a3b8; border-radius: 6px; }
.filter-panel .hint { margin: 10px 0 0; color: #475569; font-size: .875rem; }
.empty-state { padding: 28px; background: white; border: 1px dashed #cbd5e1; border-radius: 10px; }
.empty-state h2 { margin: 0 0 8px; font-size: 1.125rem; }
.empty-state p { margin: 0; color: #475569; }
:where(tbody tr):hover { background: #f8fafc; }
:where(tbody tr):focus-within { background: #eff6ff; }
body {
  font-family: var(--font-ui);
  font-size: var(--text-base);
  line-height: 1.5;
  color: var(--text-primary);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-ui);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.02em;
  text-wrap: balance;
}
h1 { font-size: var(--text-heading); }
h2 { font-size: 1.375rem; }
h3 { font-size: 1.125rem; }
h4, h5, h6 { font-size: 1rem; }

input, select, textarea, button {
  font: inherit;
  letter-spacing: normal;
}
input, select, textarea { line-height: 1.5; }
input::placeholder, textarea::placeholder { color: #64748b; opacity: 1; }
button, .btn-primary, .btn-secondary, .accion {
  font-weight: 600;
  line-height: 1.4;
}
label, dt { font-size: var(--text-sm); line-height: 1.5; }
table { font-size: var(--text-sm); line-height: 1.5; }
th { font-weight: 600; }
td { font-variant-numeric: tabular-nums; }
.hint, .ayuda, .subtitle, .welcome { line-height: 1.6; }
.badge, .estado { font-weight: 600; line-height: 1.4; }

/* Keyboard focus also covers screens without component-specific focus styles. */
:is(a, button, input, select, textarea, summary, [tabindex]):focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 3px;
}

/* Base sizing keeps padding inside controls and cards. */
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; }
app-root { display: block; min-width: 0; }
img, video, canvas, svg { max-width: 100%; height: auto; }
input, select, textarea, button { max-width: 100%; }
fieldset { min-width: 0; }
:where(h1, h2, h3, h4, p, a, label, dd) { overflow-wrap: anywhere; }
:where(.page-header, .dashboard-header, .detail-header, .section-title, .series-header) { flex-wrap: wrap; gap: 16px; }
:where(.actions, .acciones, .buttons, .pagination, .paginacion) { flex-wrap: wrap; }
:where(.table-container, .table-scroll, .tabla, .series-table) { width: 100%; max-width: 100%; min-width: 0; overflow-x: auto; }
:where(.card, .form-card, .panel, .grid > *, .form-grid > *, .grid-cards > *) { min-width: 0; }
@media (max-width: 768px) {
  :where(button, a.btn-primary, a.btn-secondary, a.accion, summary) { min-height: 44px; }
  :where(input, select, textarea) { font-size: 16px; min-height: 44px; }
}
body:has(dialog.mobile-menu[open]) { overflow: hidden; }
.table-container > table, .table-scroll > table, .tabla > table { min-width: 640px; }
.series-table > table { min-width: 360px; }

