.layout {
  display: flex;
  min-height: 100vh;
  background: #f5f6f8;
}

.main-area {
  flex: 1;
  display: flex;
  flex-direction: column;
}

.content {
  flex: 1;
  padding: 24px;
}:host { display: block; min-width: 0; }
.main-area, .content { min-width: 0; max-width: 100%; }
.desktop-sidebar {
  flex: 0 0 240px;
  position: sticky;
  top: 0;
  align-self: flex-start;
  height: 100dvh;
  overflow-y: auto;
  overscroll-behavior-y: contain;
  background: #1f2937;
  scrollbar-width: thin;
  scrollbar-color: #64748b #1f2937;
}
.mobile-menu { padding: 0; border: 0; margin: 0; width: min(320px, 90vw); max-width: 90vw; height: 100dvh; max-height: 100dvh; background: #1f2937; color: white; }
.mobile-menu::backdrop { background: rgb(15 23 42 / 55%); }
.menu-panel { min-height: 100%; }
.menu-close { display: block; margin: 12px 16px 0 auto; min-height: 44px; padding: 10px 14px; border: 1px solid #64748b; border-radius: 6px; background: #374151; color: white; cursor: pointer; }
@media (max-width: 1024px) { .desktop-sidebar { display: none; } .content { padding: 20px; } }
@media (max-width: 576px) { .content { padding: 16px 12px; } }

src\\app\\layout\\navbar\\navbar.css:
.navbar {
  height: 64px;
  background: white;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 24px;

  border-bottom: 1px solid #e5e7eb;
}

.navbar h3 {
  margin: 0;
  font-size: 1.0625rem;
  letter-spacing: -0.01em;
}

.navbar-actions {
  font-size: var(--text-sm);
  display: flex;
  align-items: center;
  gap: 16px;
}

.navbar-actions button {
  border: none;
  background: #1f2937;
  color: white;

  padding: 8px 14px;

  border-radius: 5px;

  cursor: pointer;
}:host { display: block; min-width: 0; }
.navbar { height: auto; min-height: 64px; gap: 16px; padding-top: 10px; padding-bottom: 10px; }
.navbar-brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.navbar-actions { min-width: 0; flex-wrap: wrap; justify-content: flex-end; }
.navbar-actions span { overflow-wrap: anywhere; min-width: 0; }
.navbar-actions button { flex-shrink: 0; min-height: 44px; }
.menu-toggle { display: none; flex-shrink: 0; width: 44px; min-height: 44px; border: 1px solid #d1d5db; border-radius: 6px; background: white; color: #1f2937; font-size: 24px; cursor: pointer; }
@media (max-width: 1024px) { .menu-toggle { display: block; } }
@media (max-width: 768px) {
  .navbar { flex-wrap: wrap; padding: 10px 16px; gap: 8px; }
  .navbar-brand { width: 100%; }
  .navbar h3 { font-size: 1rem; }
  .navbar-actions { width: 100%; justify-content: space-between; gap: 8px; }
  .navbar-actions span { flex: 1; font-size: .875rem; }
}

src\\app\\layout\\sidebar\\sidebar.css:
.sidebar {
  width: 240px;
  min-height: 100vh;
  background: #1f2937;
  color: white;
  padding: 20px;
  box-sizing: border-box;
}

.logo {
  margin-bottom: 35px;
}
.nav-section { margin: 18px 12px 2px; color: #b8c5d6; font-size: .75rem; font-weight: 600; letter-spacing: .04em; }

.logo h2 {
  margin: 0;
  font-size: 24px;
}

.logo span {
  font-size: 13px;
  color: #9ca3af;
}

nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

nav a {
  font-size: var(--text-sm);
  font-weight: 500;
  line-height: 1.5;
  text-decoration: none;
  color: #d1d5db;
  padding: 10px 12px;
  border-radius: 6px;
  transition: 0.2s;
}

nav a:hover {
  background: #374151;
  color: white;
}

nav a.active {
  font-weight: 600;
  background: #4b5563;
  color: white;
}:host { display: block; }
nav a:focus-visible { outline-color: #93c5fd; }
nav a { min-height: 44px; display: flex; align-items: center; }
