  border-top: 1px solid #e5e7eb;
}

.observation {
  margin-top: 12px;

  padding: 10px;

  background: #f9fafb;

  border-radius: 6px;

  font-size: 12px;
}

details {
  margin-top: 15px;
}

details summary {
  cursor: pointer;

  font-weight: 600;

  font-size: 12px;
}

.detail-row {
  display: flex;
  justify-content: space-between;

  padding: 9px 0;

  border-bottom: 1px solid #f3f4f6;
}

.detail-row div {
  display: flex;
  flex-direction: column;
}

.detail-row span {
  color: #6b7280;

  font-size: 11px;
}

/* SERIES */

.series-grid {
  display: grid;

  grid-template-columns:
    repeat(
      auto-fit,
      minmax(min(100%, 330px), 1fr)
    );

  gap: 16px;
}

.series-card {
  position: relative;

  padding: 18px;

  background: white;

  border: 1px solid #e5e7eb;

  border-radius: 9px;
}

.series-card h4 {
  margin: 0 0 15px;
}

.series-unit {
  position: absolute;

  top: 18px;
  right: 18px;

  color: #9ca3af;

  font-size: 11px;
}

.series-table {
  max-height: 300px;

  overflow-y: auto;
}

table {
  width: 100%;

  border-collapse: collapse;
}

th,
td {
  padding: 8px 10px;

  text-align: left;

  border-bottom: 1px solid #e5e7eb;
}

th {
  color: #6b7280;

  font-size: 11px;
}

td {
  font-size: 12px;
}

/* ESTADOS */

.state-card,
.error-card {
  padding: 30px;

  text-align: center;

  background: white;

  border:
    1px solid #e5e7eb;

  border-radius: 10px;
}

.error-card {
  color: #991b1b;

  background: #fef2f2;
}

.spinner {
  width: 30px;
  height: 30px;

  margin: 0 auto 12px;

  border:
    3px solid #e5e7eb;

  border-top-color:
    #374151;

  border-radius: 50%;

  animation:
    spin 0.8s linear infinite;
}

@keyframes spin {

  to {
    transform: rotate(360deg);
  }

}

@media (
  max-width: 1024px
) {

  .page-header {
    flex-direction: column;

    align-items: stretch;
  }

  .evaluation-summary {
    grid-template-columns:
      repeat(2, 1fr);
  }

}

@media (
  max-width: 576px
) {

  .evaluation-summary {
    grid-template-columns: 1fr;
  }

}
